import{z as B,x as s,o as e,c as l,q as A,j as o,D as E,d as t,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"数据与计算收束","description":"","frontmatter":{"title":"数据与计算收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ec-map.md","filePath":"econ/ec-map.md","lastUpdated":1791413859000}'),c={name:"econ/ec-map.md"};function d(p,a,h,m,D,_){const n=s("Mermaid");return e(),l("div",null,[a[2]||(a[2]=A('<h1 id="数据与计算收束" tabindex="-1">数据与计算收束 <a class="header-anchor" href="#数据与计算收束" aria-label="Permalink to &quot;数据与计算收束&quot;">​</a></h1><div class="epigraph"><p>实证结论的可信度是乘法：识别、测量、覆盖、复现、成本，任何一项为零，乘积为零。</p><footer>—— 据 Athey 2018 与 Einav and Levin, Science 2014 的论断整理</footer></div><p><a href="/econ/ec-scaling-computation">上一课</a>把规模化的阶梯与瓶颈定位钉住，计算这半边收齐了。本课是「经济数据与计算」的最后一课，本课程到此收束：把五课收成一张图，交还给整门实证方法的主线——数据与计算不生产可信结论，它们决定识别设计的功夫有多少能落袋。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五课合起来回答一个问题：一条实证结论凭什么可信。<a href="/econ/ec-data-sources">来源与口径</a>决定构念是否成立；<a href="/econ/ec-administrative-data">行政数据</a>决定覆盖与追踪能到谁；<a href="/econ/ec-bigdata-survey-fusion">融合</a>决定偏能不能被校；<a href="/econ/ec-reproducible-computing">复现环境</a>决定数字可不可以重新得到；<a href="/econ/ec-scaling-computation">规模化</a>决定想法可不可行、容差有没有说谎。这五项与识别是乘法不是加法：任何一项为零，<a href="/econ/potential-outcomes">潜在结果</a>层面的精巧都无处安放。<span class="marginnote">直觉类比：乘法关系就是链条承重——五节链环，断一节全断。数值上，识别做得再好记 0.9，口径错得离谱记 0.1、数字重跑不出来记 0，乘起来还是 0；加法思维会让人以为长板能补短板，乘法告诉你：短板为零时，长板毫无意义。</span></p><h3 id="一条检查序列" tabindex="-1">一条检查序列 <a class="header-anchor" href="#一条检查序列" aria-label="Permalink to &quot;一条检查序列&quot;">​</a></h3><p>读一篇实证、或自己动手之前，按序过五问。第一问：每个量是什么构念、哪一来源、什么口径与 vintage？第二问：谁不在样本里——行政边界、平台边界、不应答者？第三问：链接与校准引入了什么新误差，偏移稳不稳？第四问：结果能否一条命令重跑，种子、容差、环境锁在哪？第五问：计算瓶颈定位了吗，内层解收敛了吗？很多「显著」会在第二问或第四问掉下来；都过得去，才轮到识别假设的辩论。<span class="marginnote">常见误区：初学者容易把全部火力对准识别假设，实际上先查口径与复现成本更低——一个连一条命令都重跑不出来的结果，讨论它的识别策略是白费；顺序本身就是省时间的工具。</span></p>',7)),(e(),o(r,null,{default:E(()=>[i(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%9D%A5%E6%BA%90%E4%B8%8E%E5%8F%A3%E5%BE%84%3A%20%E6%9E%84%E5%BF%B5%E6%88%90%E7%AB%8B%22%5D%20--%3E%20ADM%5B%22%E8%A1%8C%E6%94%BF%3A%20%E8%A6%86%E7%9B%96%E4%B8%8E%E8%BF%BD%E8%B8%AA%22%5D%0A%20%20ADM%20--%3E%20FUS%5B%22%E8%9E%8D%E5%90%88%3A%20%E5%81%8F%E5%8F%AF%E6%A0%A1%22%5D%0A%20%20FUS%20--%3E%20REP%5B%22%E5%A4%8D%E7%8E%B0%3A%20%E6%95%B0%E5%AD%97%E5%8F%AF%E9%87%8D%E5%BE%97%22%5D%0A%20%20REP%20--%3E%20SCL%5B%22%E8%A7%84%E6%A8%A1%3A%20%E6%83%B3%E6%B3%95%E5%8F%AF%E8%A1%8C%2F%E5%AE%B9%E5%B7%AE%E8%AF%9A%E5%AE%9E%22%5D%0A%20%20SCL%20--%3E%20ID%5B%22%E8%AF%86%E5%88%AB%E8%AE%BE%E8%AE%A1%3A%20%E8%AE%A1%E9%87%8F%E7%9A%84%E8%AF%AD%E8%A8%80%22%5D%0A%20%20ID%20--%3E%20CONC%5B%22%E5%8F%AF%E4%BF%A1%E7%9A%84%E5%AE%9E%E8%AF%81%E7%BB%93%E8%AE%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p><span class="marginnote">Gentzkow–Shapiro–Taddy 2019 把国会演讲变成高维选择数据测极化——这条线索从<a href="/econ/pm-text-as-data">文本作为数据</a>的测量纪律走到本课程的口径与复现，是「新数据进经济学」的完整样本：测量、验证、进入协议、可复现交付，一环不缺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法在收束课里是一张交接图。向上，本课程把测量的语言交还给<a href="/econ/ml-causal-econ">计量课</a>与<a href="/econ/pm-specification-map">实证规范</a>：识别设计的前提在此列齐。向下，它向计算机栏要接口：数据库、调度与分布式语义按分组聚合与逐组估计的口径谈，不再往下钻。横向，它与<a href="/econ/pe-case-map">政策评估</a>和<a href="/econ/se-case-map">结构估计</a>共享同一套数据纪律——那些课的每一种设计，都默认本课程五问已经通过。</p><p>第一张图画的是五关的通过顺序；换一个问题——任一关挂掉时结论的成色——则是乘法结构的分叉图。</p>',4)),(e(),o(r,null,{default:E(()=>[i(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%7B%22%E5%93%AA%E4%B8%80%E9%A1%B9%E4%B8%BA%E9%9B%B6%22%7D%20--%3E%7C%22%E6%9E%84%E5%BF%B5%E6%88%96%E5%8F%A3%E5%BE%84%E9%94%99%22%7C%20Z1%5B%22%E7%BB%93%E8%AE%BA%E6%B5%8B%E7%9A%84%E4%B8%8D%E6%98%AF%E6%89%80%E8%AF%B4%E7%9A%84%22%5D%0A%20%20P%20--%3E%7C%22%E8%AF%A5%E5%9C%A8%E7%9A%84%E4%B8%8D%E5%9C%A8%E6%A0%B7%E6%9C%AC%22%7C%20Z2%5B%22%E6%80%BB%E4%BD%93%E5%A4%96%E6%8E%A8%E5%A4%B1%E6%95%88%22%5D%0A%20%20P%20--%3E%7C%22%E5%81%8F%E6%9C%AA%E6%A0%A1%E4%B8%94%E5%9C%A8%E6%BC%82%22%7C%20Z3%5B%22%E5%A4%A7%E6%95%B0%E5%8F%AA%E6%98%AF%E6%94%BE%E5%A4%A7%E4%BA%86%E7%9A%84%E5%81%8F%22%5D%0A%20%20P%20--%3E%7C%22%E6%95%B0%E5%AD%97%E4%B8%8D%E5%8F%AF%E9%87%8D%E5%BE%97%22%7C%20Z4%5B%22%E6%97%A0%E6%B3%95%E5%AE%A1%E8%AE%A1%2C%20%E4%BA%89%E8%AE%AE%E6%97%A0%E5%88%A4%E6%8D%AE%22%5D%0A%20%20P%20--%3E%7C%22%E7%AE%97%E4%B8%8D%E5%8A%A8%E6%88%96%E5%AE%B9%E5%B7%AE%E8%AF%B4%E8%B0%8E%22%7C%20Z5%5B%22%E6%83%B3%E6%B3%95%E8%90%BD%E4%B8%8D%E4%BA%86%E5%9C%B0%22%5D%0A%20%20Z1%20--%3E%20D%5B%22%E5%8F%AF%E4%BF%A1%E5%BA%A6%E4%B9%98%E7%A7%AF%E5%BD%92%E9%9B%B6%22%5D%0A%20%20Z2%20--%3E%20D%0A%20%20Z3%20--%3E%20D%0A%20%20Z4%20--%3E%20D%0A%20%20Z5%20--%3E%20D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么收在数据与计算而不是识别：识别的语言在计量课已经钉死，本课程补的是它的必要条件集。经验上，实证争议最多的不在「识别策略错」，而在口径错位、样本缺席、数字无法重得——这些恰恰不进论文的方法节，散落在附录与代码里。把五问变成默认动作，等于把争议从不可审的个人判断挪到可审的工件上：手册、快照、种子、容差；争论才落在判据上，不是数据上。<span class="marginnote">「可审工件」就是能被第三方独立检查的实物证据：数据手册、环境快照、随机种子、容差声明。有了它们，争论从「我信不信作者」变成「任何人重跑同一条命令能不能得到同一个数」——判断标准从信任换成了复得。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不覆盖隐私法与合规细节——进入协议只在统计机构语境下示范；数据库与分布式的工程原理在计算机栏；文本与 NLP 的测量在预测课与文本课。这些是邻接域，接口已在各课边界段写明。也要防收束课的通病：清单不是防火墙，五问通过不保证结论对，它们只保证结论可以在共同事实上辩论。数据与计算到此收束；下一课起，树回到环境与能源经济学——但每一行理论落到数据上时，都从本课程的五问重新出发。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据与计算对识别是乘法关系：构念、覆盖、偏校、复现、成本，缺一即零。</li><li>五问检查序列：构念与口径、谁缺席、链接误差、可复现性、瓶颈与容差。</li><li>实证争议的大头在方法节之外：口径、缺席与不可复得；收束的意义是把它们变成可审工件。</li><li>新数据进经济学的完整路径：测量验证、进入协议、复现交付、规模可行。</li><li>本课程到此收束：识别的语言归计量，工程的接口归计算机栏，两边的乘积才是可信实证。</li><li>出处：Athey, The Impact of Machine Learning on Economics, 2018；Einav and Levin, <em>Science</em> 2014；Gentzkow, Shapiro and Taddy, <em>Econometrica</em> 2019。</li></ul>',6))])}const u=B(c,[["render",d]]);export{F as __pageData,u as default};
